{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.warehouse_mp_performance AS WITH uc AS ( SELECT * FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 WHERE marketplace_mapped NOT IN ( \'STORE\',\'MYNTRA\',\'AJIO\',\'FLIPKART\',\'SHOPIFY\',\'AMAZON\',\'NYKAA.COM\',\'NYKAA_FASHION\',\'NOON\',\'TEST VR MALL\',\'CUSTOM\',\'B2B CORPORATE CHANNEL\',\'SNITCH HQ\',\'CRED\',\'POPCLUB\',\'SAPL_WH_TRANSFERS\',\'SNAPMINT\',\'COCOBLU_WH2\',\'COCOBLU_NORTH\',\'COCOBLU\',\'COCOBLU_WH1\' ) and order_date >= current_date-180 ), mp AS ( SELECT UPPER(TRIM(SO_NUMBER)) AS mp_so_key, SO_NUMBER AS mp_so_number, PO_NUMBER AS mp_po_number, DC_NUMBER AS mp_dc_number, LR_NO AS mp_lr_no, INVOICE_NUMBER AS mp_invoice_number, CHANNEL AS mp_channel, MARKETPLACE_NAME AS mp_marketplace_name, FACILITY AS mp_facility, CITY AS mp_city, \"Address \" AS mp_address, STATUS AS mp_status, DELIVERY_STATUS AS mp_delivery_status, CURRENT_REMARKS AS mp_current_remarks, REMARKS AS mp_remarks, LOGISTICS_PARTNER AS mp_logistics_partner, TRY_TO_NUMBER(QTY) AS mp_qty, TRY_TO_NUMBER(QTY_DISPATCHED) AS mp_qty_dispatched, TRY_TO_NUMBER(NF_UF_QTY) AS mp_nf_uf_qty, TRY_TO_NUMBER(BOX_COUNT) AS mp_box_count, TRY_TO_NUMBER(ACTUALWEIGHT) AS mp_actual_weight, NEW_SLOT AS mp_new_slot, TRY_TO_DATE(DATE, \'DD/MM/YYYY\') AS mp_date, TRY_TO_DATE(RTS_DATE, \'YYYY-MM-DD\') AS mp_rts_date, TRY_TO_DATE(SLOT_DATE, \'YYYY-MM-DD\') AS mp_slot_date, TRY_TO_DATE(PICKUP_DATE, \'YYYY-MM-DD\') AS mp_pickup_date, TRY_TO_DATE(DISPATCH_DATE, \'YYYY-MM-DD\') AS mp_dispatch_date, TRY_TO_DATE(DELIVERED_DATE, \'YYYY-MM-DD\') AS mp_delivered_date, PROCESSING_TAT AS mp_processing_tat, ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(SO_NUMBER)) ORDER BY TRY_TO_DATE(DISPATCH_DATE, \'YYYY-MM-DD\') DESC NULLS LAST ) AS rn FROM snitch_db.maplemonk.gs_marketplace_wh_tracker WHERE SO_NUMBER IS NOT NULL AND TRIM(SO_NUMBER) <> \'\' ), grn AS ( SELECT UPPER(TRIM(PO_BARCODE)) AS grn_po_barcode_key, QUANTITY AS grn_quantity, AMM_COUNT AS grn_amm_count, SHORT_QTY AS grn_short_qty, BRAND_TYPE AS grn_brand_type, LOT_STATUS AS grn_lot_status, PO_BARCODE AS grn_po_barcode, ITEM_INWARD AS grn_item_inward, GATEPASS_ID AS grn_gatepass_id, LOT_BARCODE AS grn_lot_barcode, RECEIVED_ON AS grn_received_on, VENDOR_NAME AS grn_vendor_name, WAREHOUSE_ID AS grn_warehouse_id, QA_FAIL_TOTAL AS grn_qa_fail_total, QA_PASS_TOTAL AS grn_qa_pass_total, INVOICE_NUMBER AS grn_invoice_number, _AB_SOURCE_FILE_URL AS grn_ab_source_file_url, _AB_ADDITIONAL_PROPERTIES AS grn_ab_additional_properties, _AB_SOURCE_FILE_LAST_MODIFIED AS grn_ab_source_file_last_modified, _AIRBYTE_AB_ID AS grn_airbyte_ab_id, _AIRBYTE_EMITTED_AT AS grn_airbyte_emitted_at, _AIRBYTE_NORMALIZED_AT AS grn_airbyte_normalized_at, _AIRBYTE_S3_MP_GRN_DATA_HASHID AS grn_airbyte_s3_mp_grn_data_hashid, ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(PO_BARCODE)) ORDER BY RECEIVED_ON DESC NULLS LAST, _AIRBYTE_EMITTED_AT DESC NULLS LAST ) AS rn FROM snitch_db.maplemonk.s3_mp_grn_data WHERE PO_BARCODE IS NOT NULL AND TRIM(PO_BARCODE) <> \'\' ), joined AS ( SELECT uc.*, mp.mp_so_number, mp.mp_po_number, mp.mp_dc_number, mp.mp_lr_no, mp.mp_invoice_number, mp.mp_channel, mp.mp_marketplace_name, mp.mp_facility, mp.mp_city, mp.mp_address, mp.mp_status, mp.mp_delivery_status, mp.mp_current_remarks, mp.mp_remarks, mp.mp_logistics_partner, mp.mp_qty, mp.mp_qty_dispatched, mp.mp_nf_uf_qty, mp.mp_box_count, mp.mp_actual_weight, mp.mp_new_slot, mp.mp_date, mp.mp_rts_date, mp.mp_slot_date, mp.mp_pickup_date, mp.mp_dispatch_date, mp.mp_delivered_date, mp.mp_processing_tat, CASE WHEN mp.mp_so_key IS NOT NULL THEN 1 ELSE NULL END AS mp_tracker_match_flag, COALESCE(dispatched_timestamp, packed_time, packed_timestamp) AS wh_dispatch_ts, grn.grn_quantity, grn.grn_amm_count, grn.grn_short_qty, grn.grn_brand_type, grn.grn_lot_status, grn.grn_po_barcode, grn.grn_item_inward, grn.grn_gatepass_id, grn.grn_lot_barcode, grn.grn_received_on, grn.grn_vendor_name, grn.grn_warehouse_id, grn.grn_qa_fail_total, grn.grn_qa_pass_total, grn.grn_invoice_number, grn.grn_ab_source_file_url, grn.grn_ab_additional_properties, grn.grn_ab_source_file_last_modified, grn.grn_airbyte_ab_id, grn.grn_airbyte_emitted_at, grn.grn_airbyte_normalized_at, grn.grn_airbyte_s3_mp_grn_data_hashid FROM uc LEFT JOIN mp ON UPPER(TRIM(uc.order_name)) = mp.mp_so_key AND (mp.rn = 1 OR mp.rn IS NULL) LEFT JOIN grn ON UPPER(TRIM(mp.mp_po_number)) = grn.grn_po_barcode_key AND (grn.rn = 1 OR grn.rn IS NULL) ) SELECT joined.*, CASE WHEN mp_tracker_match_flag IS NULL THEN \'NO TRACKER MATCH\' WHEN sale_order_item_status = \'CANCELLED\' THEN \'CANCELLED\' WHEN sale_order_item_status = \'UNFULFILLABLE\' THEN \'UNFULFILLABLE\' WHEN mp_dispatch_date IS NULL AND wh_dispatch_ts IS NULL THEN \'BREACHED - PENDING FOR PROCESS\' WHEN mp_dispatch_date IS NULL THEN \'PENDING - NO TRACKER DISPATCH DATE\' WHEN wh_dispatch_ts IS NULL THEN \'BREACHED - PENDING FOR PROCESS\' WHEN wh_dispatch_ts::DATE <= mp_dispatch_date THEN \'WITHIN SLA\' ELSE \'BREACHED\' END AS processing_sla, CASE WHEN mp_tracker_match_flag IS NULL THEN \'NO TRACKER MATCH\' WHEN sale_order_item_status = \'CANCELLED\' THEN \'CANCELLED\' WHEN mp_slot_date IS NULL THEN \'PENDING - NO SLOT DATE\' WHEN mp_delivered_date IS NULL THEN \'BREACHED-PENDING FOR PROCESS\' WHEN mp_delivered_date <= mp_slot_date THEN \'WITHIN SLA\' ELSE \'BREACHED\' END AS logistics_sla, DATEDIFF(\'day\', uc_created::DATE, wh_dispatch_ts::DATE) AS processing_days, DATEDIFF(\'day\', wh_dispatch_ts::DATE, mp_delivered_date) AS delivery_transit_days, DATEDIFF(\'day\', mp_dispatch_date, wh_dispatch_ts::DATE) AS processing_sla_lag_days, DATEDIFF(\'day\', mp_slot_date, mp_delivered_date) AS logistics_sla_lag_days, CASE WHEN mp_qty > 0 THEN ROUND(mp_qty_dispatched / mp_qty, 4) END AS fill_rate, CASE WHEN mp_delivered_date IS NULL THEN DATEDIFF(\'day\', uc_created::DATE, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::DATE) END AS open_order_ageing_days, CASE WHEN dispatched_timestamp IS NOT NULL THEN 1 ELSE 0 END AS dispatched_flag, CASE WHEN grn_received_on IS NOT NULL THEN 1 ELSE 0 END AS delivered_flag FROM joined ; select * from snitch_db.maplemonk.warehouse_mp_performance;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            